//! Deterministic generators for bench objects: note values, session
//! content, and a native session over generated bytes.

use std::any::Any;
use std::io::Write as _;
use std::time::SystemTime;

use gage_session::{
    ContentSink, ContentSource, Driver, DriverError, NativeSession, SessionAttrs, Source,
    StoredSession,
};
use rand::rngs::StdRng;
use rand::{Rng, RngCore, SeedableRng};

/// Names notes are drawn from. A small vocabulary makes a name filter
/// selective enough to measure.
pub const NOTE_NAMES: [&str; 8] = [
    "project-summary",
    "session-summary",
    "finding",
    "open-code",
    "comment",
    "todo",
    "risk",
    "question",
];

pub struct Generator {
    rng: StdRng,
}

impl Generator {
    pub fn new(seed: u64) -> Self {
        Generator {
            rng: StdRng::seed_from_u64(seed),
        }
    }

    /// A uniform index below `len`.
    pub fn pick(&mut self, len: usize) -> usize {
        self.rng.random_range(0..len)
    }

    pub fn note_name(&mut self) -> &'static str {
        NOTE_NAMES
            .get(self.rng.random_range(0..NOTE_NAMES.len()))
            .expect("range is bounded by the array length")
    }

    /// Lowercase words separated by spaces, `bytes` long.
    pub fn text(&mut self, bytes: usize) -> String {
        let mut out = String::with_capacity(bytes);
        while out.len() < bytes {
            let len = self.rng.random_range(2..10usize);
            for _ in 0..len {
                out.push(self.rng.random_range(b'a'..=b'z') as char);
            }
            out.push(' ');
        }
        out.truncate(bytes);
        out
    }

    /// JSONL resembling a harness transcript, at least `bytes` long,
    /// ending on a line boundary. Content is append-only by
    /// construction: `grow` appends further lines to it.
    pub fn session_content(&mut self, bytes: usize) -> String {
        let mut out = String::with_capacity(bytes + 512);
        let mut line = 0u64;
        while out.len() < bytes {
            self.append_line(&mut out, line);
            line += 1;
        }
        out
    }

    /// Append `lines` more lines to `content`.
    pub fn grow(&mut self, content: &mut String, lines: usize) {
        let start = content.lines().count() as u64;
        for i in 0..lines as u64 {
            self.append_line(content, start + i);
        }
    }

    fn append_line(&mut self, out: &mut String, line: u64) {
        let uuid = self.rng.next_u64();
        let text_len = self.rng.random_range(80..400usize);
        let text = self.text(text_len);
        let role = if line.is_multiple_of(2) {
            "user"
        } else {
            "assistant"
        };
        out.push_str(&format!(
            "{{\"uuid\":\"{uuid:016x}\",\"type\":\"{role}\",\"line\":{line},\"message\":{{\"role\":\"{role}\",\"content\":\"{text}\"}}}}\n"
        ));
    }
}

/// The files a synthetic session presents for `content`: the
/// transcript, a subagent transcript under a subdirectory, and a small
/// metadata file, which is the shape the Claude driver produces. The
/// subagent transcript is the first quarter of the content on a line
/// boundary. `verify` reads every file back through this same function.
pub fn session_files(id: &str, content: &str) -> Vec<(String, Vec<u8>)> {
    let quarter = content.len() / 4;
    let cut = content
        .get(..quarter)
        .and_then(|head| head.rfind('\n'))
        .map_or(0, |i| i + 1);
    let (subagent, _) = content.split_at(cut);
    vec![
        ("session.jsonl".to_string(), content.as_bytes().to_vec()),
        (
            format!("subagents/agent-{id}.jsonl"),
            subagent.as_bytes().to_vec(),
        ),
        (
            format!("subagents/agent-{id}.meta.json"),
            format!("{{\"agent\":\"{id}\"}}\n").into_bytes(),
        ),
    ]
}

/// A native session over generated bytes.
pub struct SyntheticSession {
    id: String,
    files: Vec<(String, Vec<u8>)>,
    attrs: SyntheticAttrs,
}

struct SyntheticAttrs {
    size: u64,
}

impl SessionAttrs for SyntheticAttrs {
    fn mtime(&self) -> Option<SystemTime> {
        None
    }
    fn size(&self) -> Option<u64> {
        Some(self.size)
    }
    fn is_empty(&self) -> Option<bool> {
        None
    }
    fn project_name(&self) -> Option<&str> {
        None
    }
    fn title(&self) -> Option<&str> {
        None
    }
    fn model(&self) -> Option<&str> {
        None
    }
    fn message_count(&self) -> Option<u64> {
        None
    }
}

impl SyntheticSession {
    pub fn new(id: &str, content: &str) -> Self {
        let files = session_files(id, content);
        let size = files.iter().map(|(_, b)| b.len() as u64).sum();
        SyntheticSession {
            id: id.to_string(),
            files,
            attrs: SyntheticAttrs { size },
        }
    }

    pub fn files(&self) -> &[(String, Vec<u8>)] {
        &self.files
    }
}

impl NativeSession for SyntheticSession {
    fn native_id(&self) -> &str {
        &self.id
    }

    fn session_type(&self) -> &str {
        "bench"
    }

    fn attrs(&self) -> &dyn SessionAttrs {
        &self.attrs
    }

    fn as_any(&self) -> &dyn Any {
        self
    }
}

/// Driver for [`SyntheticSession`]. Only `write_native` is exercised
/// by the bench; other trait methods return errors.
pub struct SyntheticDriver;

pub const SYNTHETIC_CONTENT_FORMAT: &str = "synth 1";

impl Driver for SyntheticDriver {
    fn name(&self) -> &'static str {
        "bench"
    }

    fn version(&self) -> &'static str {
        "0"
    }

    fn schemes(&self) -> &'static [&'static str] {
        &["bench"]
    }
    fn open_source(&self, _source: &str) -> Result<Box<dyn Source>, DriverError> {
        Err(DriverError::Other("open_source not used".into()))
    }
    fn write_native(
        &self,
        session: &mut dyn NativeSession,
        sink: &mut dyn ContentSink,
    ) -> Result<String, DriverError> {
        let synth = session
            .as_any()
            .downcast_ref::<SyntheticSession>()
            .ok_or_else(|| DriverError::Other("not a SyntheticSession".into()))?;
        for (path, bytes) in synth.files() {
            let mut w = sink.create(path).map_err(DriverError::Io)?;
            w.write_all(bytes).map_err(DriverError::Io)?;
        }
        Ok(SYNTHETIC_CONTENT_FORMAT.to_string())
    }

    fn read_stored(
        &self,
        _native_id: String,
        _content_format: &str,
        _source: Box<dyn ContentSource>,
    ) -> Result<Box<dyn StoredSession>, DriverError> {
        Err(DriverError::Other("read_stored not used".into()))
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn generator_is_deterministic_for_a_seed() {
        let a = Generator::new(7).session_content(4096);
        let b = Generator::new(7).session_content(4096);
        assert_eq!(a, b);
        assert!(a.len() >= 4096);
        assert!(a.ends_with('\n'));
    }

    #[test]
    fn session_files_cut_on_a_line_boundary() {
        let content = Generator::new(3).session_content(4096);
        let files = session_files("s", &content);
        assert_eq!(files.len(), 3);
        assert_eq!(files[0].1, content.as_bytes());
        let subagent = std::str::from_utf8(&files[1].1).unwrap();
        assert!(subagent.is_empty() || subagent.ends_with('\n'));
        assert!(content.starts_with(subagent));
    }

    #[test]
    fn grow_appends_whole_lines() {
        let mut g = Generator::new(1);
        let mut content = g.session_content(1024);
        let before = content.lines().count();
        g.grow(&mut content, 3);
        assert_eq!(content.lines().count(), before + 3);
    }
}
